```js
// Applies a per-face bounce off a brick and pushes the ball out so it no
// longer overlaps. Returns true if the ball was deflected.
// - top/bottom hit (smaller vertical penetration) => flip vy
// - side hit (smaller horizontal penetration)     => flip vx
// - corner (equal penetration)                    => flip both
export function bounceOffBrick(ball, brick) {
  // Penetration on each side of the brick (how far the ball embeds).
  const fromTop    = ball.y + ball.r - brick.y;
  const fromBottom = brick.y + brick.h - (ball.y - ball.r);
  const fromLeft   = ball.x + ball.r - brick.x;
  const fromRight  = brick.x + brick.w - (ball.x - ball.r);

  // The axis with the smaller embed amounts is the face actually hit.
  const penX = Math.min(fromLeft, fromRight);
  const penY = Math.min(fromTop, fromBottom);

  if (penY < penX) {
    // top or bottom face
    if (fromTop < fromBottom) {
      ball.y = brick.y - ball.r;       // push above
      ball.vy = -Math.abs(ball.vy);    // bounce up
    } else {
      ball.y = brick.y + brick.h + ball.r; // push below
      ball.vy = Math.abs(ball.vy);         // bounce down
    }
  } else if (penX < penY) {
    if (fromLeft < fromRight) {
      ball.x = brick.x - ball.r;       // push left
      ball.vx = -Math.abs(ball.vx);    // bounce left
    } else {
      ball.x = brick.x + brick.w + ball.r; // push right
      ball.vx = Math.abs(ball.vx);         // bounce right
    }
  } else {
    // corner: equal penetration
    if (fromLeft < fromRight) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
    if (fromTop < fromBottom) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  }
  return true;
}
```

