// Bricks: swept collision + bounce + score + drawing, all in one place.
const prevX = state.prevX ?? state.ball.x;
const prevY = state.prevY ?? state.ball.y;
let bounced = false;
for (const brick of state.bricks) {
  if (!brick.alive) continue;

  const hit = sweepBrick(state.ball, prevX, prevY, brick);
  if (hit !== null) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    // Bounce at most ONCE per pass: a seam (8 px gap) overlaps two bricks and
    // a second flip would cancel the first (`vy = -vy` twice), letting the
    // ball straight through. The earliest contact picks the face.
    if (!bounced) {
      state.prevX = state.ball.x;
      state.prevY = state.ball.y;
      bounceOffBrick(state.ball, hit);
      state.prevX = state.ball.x;
      state.prevY = state.ball.y;
      bounced = true;
    }
  }

  ctx.fillStyle = brickColor(brick.row);
  ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
}

